codeExamples.tech1Snippet:
use actix_web::{get, App, HttpServer, Responder};

#[get("/")]
async fn hallo() -> impl Responder {
    "Hallo, Welt!"
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    HttpServer::new(|| App::new().service(hallo))
        .bind(("127.0.0.1", 8080))?
        .run()
        .await
}

